from threading import Lock
from typing import Any

from models import CacheEntry, normalize_key


class CacheBackend:
    def __init__(self) -> None:
        self._lock = Lock()
        self._entries: dict[str, CacheEntry] = {}

    def get(self, key: str) -> CacheEntry | None:
        target = normalize_key(key)
        if not target:
            return None
        with self._lock:
            return self._entries.get(target)

    def set(self, entry: CacheEntry) -> None:
        target = normalize_key(entry.key)
        if not target:
            raise ValueError("cache key is required")
        with self._lock:
            self._entries[target] = CacheEntry(
                key=target,
                value=entry.value,
                source_version=entry.source_version,
                expires_at_ms=entry.expires_at_ms,
                created_at_ms=entry.created_at_ms,
            )

    def delete(self, key: str) -> bool:
        target = normalize_key(key)
        if not target:
            return False
        with self._lock:
            existed = target in self._entries
            if existed:
                del self._entries[target]
            return existed

    def clear(self) -> None:
        with self._lock:
            self._entries.clear()

    def has(self, key: str) -> bool:
        target = normalize_key(key)
        if not target:
            return False
        with self._lock:
            return target in self._entries

    def count(self) -> int:
        with self._lock:
            return len(self._entries)

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._entries.keys())

    def snapshot(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {
                key: {
                    "value": entry.value,
                    "source_version": entry.source_version,
                    "expires_at_ms": entry.expires_at_ms,
                    "created_at_ms": entry.created_at_ms,
                }
                for key, entry in self._entries.items()
            }

    def bulk_delete(self, keys: list[str]) -> int:
        deleted = 0
        with self._lock:
            for raw_key in keys:
                key = normalize_key(raw_key)
                if not key:
                    continue
                if key in self._entries:
                    del self._entries[key]
                    deleted += 1
        return deleted

    def upsert_value(
        self,
        *,
        key: str,
        value: str,
        source_version: int,
        expires_at_ms: int,
        created_at_ms: int,
    ) -> None:
        entry = CacheEntry(
            key=normalize_key(key),
            value=value,
            source_version=source_version,
            expires_at_ms=expires_at_ms,
            created_at_ms=created_at_ms,
        )
        self.set(entry)

    def get_many(self, keys: list[str]) -> dict[str, CacheEntry]:
        out: dict[str, CacheEntry] = {}
        for raw_key in keys:
            key = normalize_key(raw_key)
            if not key:
                continue
            item = self.get(key)
            if item is not None:
                out[key] = item
        return out

    def replace_all(self, entries: list[CacheEntry]) -> None:
        with self._lock:
            self._entries.clear()
            for entry in entries:
                key = normalize_key(entry.key)
                if not key:
                    continue
                self._entries[key] = CacheEntry(
                    key=key,
                    value=entry.value,
                    source_version=entry.source_version,
                    expires_at_ms=entry.expires_at_ms,
                    created_at_ms=entry.created_at_ms,
                )

