from __future__ import annotations

from threading import Lock
from time import monotonic_ns


class Clock:
    def __init__(self) -> None:
        self._lock = Lock()
        self._offset_ms = 0
        self._frozen_ms: int | None = None

    def now_ms(self) -> int:
        with self._lock:
            if self._frozen_ms is not None:
                return self._frozen_ms + self._offset_ms
            base = monotonic_ns() // 1_000_000
            return int(base + self._offset_ms)

    def set_offset_ms(self, offset_ms: int) -> None:
        with self._lock:
            self._offset_ms = int(offset_ms)

    def advance_ms(self, amount_ms: int) -> None:
        with self._lock:
            if self._frozen_ms is None:
                self._offset_ms += int(amount_ms)
            else:
                self._frozen_ms += int(amount_ms)

    def freeze(self, now_ms: int | None = None) -> None:
        with self._lock:
            if now_ms is None:
                now_ms = monotonic_ns() // 1_000_000
            self._frozen_ms = int(now_ms)

    def unfreeze(self) -> None:
        with self._lock:
            self._frozen_ms = None

    def is_frozen(self) -> bool:
        with self._lock:
            return self._frozen_ms is not None

    def snapshot(self) -> dict[str, int | bool]:
        with self._lock:
            frozen = self._frozen_ms is not None
            return {
                "offset_ms": self._offset_ms,
                "is_frozen": frozen,
                "frozen_ms": self._frozen_ms or 0,
            }

    def reset(self) -> None:
        with self._lock:
            self._offset_ms = 0
            self._frozen_ms = None

    def freeze_now(self) -> int:
        current = self.now_ms()
        self.freeze(current)
        return current

