from dataclasses import dataclass
from threading import Lock
from typing import Any


@dataclass(frozen=True)
class Event:
    event_type: str
    key: str
    payload: dict[str, Any]


class EventLog:
    def __init__(self) -> None:
        self._lock = Lock()
        self._events: list[Event] = []

    def add(self, event_type: str, key: str, payload: dict[str, Any] | None = None) -> None:
        item = Event(
            event_type=event_type.strip() or "unknown",
            key=key.strip().lower(),
            payload=dict(payload or {}),
        )
        with self._lock:
            self._events.append(item)

    def count(self) -> int:
        with self._lock:
            return len(self._events)

    def list_all(self) -> list[Event]:
        with self._lock:
            return list(self._events)

    def by_key(self, key: str) -> list[Event]:
        target = key.strip().lower()
        with self._lock:
            return [event for event in self._events if event.key == target]

    def by_type(self, event_type: str) -> list[Event]:
        target = event_type.strip()
        with self._lock:
            return [event for event in self._events if event.event_type == target]

    def summary(self) -> dict[str, int]:
        with self._lock:
            values: dict[str, int] = {}
            for event in self._events:
                values[event.event_type] = values.get(event.event_type, 0) + 1
            return values

    def clear(self) -> None:
        with self._lock:
            self._events.clear()

    def latest_for_key(self, key: str) -> Event | None:
        events = self.by_key(key)
        if not events:
            return None
        return events[-1]

