from threading import Lock
from typing import Any

from models import DataRecord, normalize_key


class DataRepository:
    def __init__(self) -> None:
        self._lock = Lock()
        self._records: dict[str, DataRecord] = {}
        self._versions: dict[str, int] = {}

    def seed(self, values: dict[str, str], now_ms: int) -> None:
        with self._lock:
            self._records.clear()
            self._versions.clear()
            for raw_key, raw_value in values.items():
                key = normalize_key(raw_key)
                if not key:
                    raise ValueError("invalid seed key")
                version = 1
                record = DataRecord(
                    key=key,
                    value=str(raw_value),
                    version=version,
                    updated_at_ms=now_ms,
                    metadata={"seeded": True},
                )
                record.validate()
                self._records[key] = record
                self._versions[key] = version

    def get(self, key: str) -> DataRecord | None:
        target = normalize_key(key)
        if not target:
            return None
        with self._lock:
            return self._records.get(target)

    def set(self, key: str, value: str, now_ms: int, metadata: dict[str, Any] | None = None) -> DataRecord:
        target = normalize_key(key)
        if not target:
            raise ValueError("key is required")
        with self._lock:
            next_version = self._versions.get(target, 0) + 1
            record = DataRecord(
                key=target,
                value=str(value),
                version=next_version,
                updated_at_ms=now_ms,
                metadata=dict(metadata or {}),
            )
            record.validate()
            self._records[target] = record
            self._versions[target] = next_version
            return record

    def delete(self, key: str) -> bool:
        target = normalize_key(key)
        if not target:
            return False
        with self._lock:
            existed = target in self._records
            if existed:
                del self._records[target]
            return existed

    def list_keys(self) -> list[str]:
        with self._lock:
            return sorted(self._records.keys())

    def snapshot(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {
                key: {
                    "value": record.value,
                    "version": record.version,
                    "updated_at_ms": record.updated_at_ms,
                }
                for key, record in self._records.items()
            }

    def export_versions(self) -> dict[str, int]:
        with self._lock:
            return dict(self._versions)

    def count(self) -> int:
        with self._lock:
            return len(self._records)

    def clear(self) -> None:
        with self._lock:
            self._records.clear()
            self._versions.clear()

    def set_many(self, items: dict[str, str], now_ms: int, source: str = "batch") -> list[DataRecord]:
        written: list[DataRecord] = []
        for key, value in items.items():
            record = self.set(key, value, now_ms, metadata={"source": source})
            written.append(record)
        return written

    def exists(self, key: str) -> bool:
        target = normalize_key(key)
        if not target:
            return False
        with self._lock:
            return target in self._records

    def get_many(self, keys: list[str]) -> dict[str, DataRecord]:
        out: dict[str, DataRecord] = {}
        for raw_key in keys:
            key = normalize_key(raw_key)
            if not key:
                continue
            record = self.get(key)
            if record is not None:
                out[key] = record
        return out

    def highest_version(self) -> int:
        with self._lock:
            if not self._versions:
                return 0
            return max(self._versions.values())

    def upsert_with_version(
        self,
        key: str,
        value: str,
        expected_min_version: int,
        now_ms: int,
    ) -> DataRecord:
        current = self.get(key)
        if current is not None and current.version < expected_min_version:
            raise ValueError("version_too_old")
        return self.set(key, value, now_ms, metadata={"expected_min_version": expected_min_version})

