from typing import Any

from cache_backend import CacheBackend
from clock import Clock
from event_log import EventLog
from invalidation import InvalidationManager
from models import CacheEntry, normalize_key, read_result, write_result
from policies import default_policy, expires_at, is_within_stale_grace, should_force_refresh
from repository import DataRepository


class DataService:
    def __init__(
        self,
        *,
        repository: DataRepository,
        cache: CacheBackend,
        invalidation: InvalidationManager,
        event_log: EventLog,
        clock: Clock,
    ) -> None:
        self._repository = repository
        self._cache = cache
        self._invalidation = invalidation
        self._event_log = event_log
        self._clock = clock
        self._policy = default_policy()

    def read(self, key: str, hint: str = "") -> dict[str, Any]:
        target = normalize_key(key)
        if not target:
            return read_result(False, "", "", "none", 0, "invalid_key")

        now_ms = self._clock.now_ms()
        force_refresh = should_force_refresh(hint)
        entry = self._cache.get(target)
        if entry is not None and not force_refresh:
            if not entry.is_expired(now_ms):
                self._event_log.add("cache_hit", target, {"version": entry.source_version})
                return read_result(True, target, entry.value, "cache", entry.source_version, "ok")
            if is_within_stale_grace(now_ms, entry.expires_at_ms, self._policy.stale_grace_ms):
                self._event_log.add("cache_stale_grace_hit", target, {"version": entry.source_version})
                return read_result(True, target, entry.value, "cache_stale", entry.source_version, "stale_grace")

        record = self._repository.get(target)
        if record is None:
            self._event_log.add("read_miss", target, {})
            return read_result(False, target, "", "repository", 0, "not_found")

        cache_item = CacheEntry(
            key=target,
            value=record.value,
            source_version=record.version,
            expires_at_ms=expires_at(now_ms, self._policy.ttl_ms),
            created_at_ms=now_ms,
        )
        self._cache.set(cache_item)
        self._event_log.add("cache_fill", target, {"version": record.version})
        return read_result(True, target, record.value, "repository", record.version, "ok")

    def write(self, key: str, value: str, metadata: dict[str, Any] | None = None) -> dict[str, Any]:
        target = normalize_key(key)
        if not target:
            return write_result(False, "", "", 0, "invalid_key")
        now_ms = self._clock.now_ms()
        record = self._repository.set(target, value, now_ms, metadata=metadata)
        self._event_log.add("write_committed", target, {"version": record.version})

        # BUG: invalidation is queued but not flushed in write path.
        # Reads immediately after write can still return stale cache entries.
        self._invalidation.queue_key(target)
        return write_result(True, target, record.value, record.version, "ok")

    def flush_invalidation(self) -> int:
        deleted = self._invalidation.flush()
        self._event_log.add("invalidation_flush_manual", "*", {"deleted": deleted})
        return deleted

    def diagnostics(self) -> dict[str, Any]:
        return {
            "repository": self._repository.snapshot(),
            "cache": self._cache.snapshot(),
            "events": self._event_log.summary(),
            "invalidation": self._invalidation.snapshot(),
            "clock": self._clock.snapshot(),
        }

    def warm_cache(self, keys: list[str]) -> dict[str, int]:
        warmed = 0
        missed = 0
        for key in keys:
            result = self.read(key)
            if result.get("ok"):
                warmed += 1
            else:
                missed += 1
        return {"warmed": warmed, "missed": missed}

    def write_many(self, items: dict[str, str], source: str = "bulk_update") -> dict[str, int]:
        success = 0
        failed = 0
        for key, value in items.items():
            result = self.write(key, value, metadata={"source": source})
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed}

    def read_many(self, keys: list[str], hint: str = "") -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        for key in keys:
            out.append(self.read(key, hint=hint))
        return out

    def force_refresh(self, key: str) -> dict[str, Any]:
        return self.read(key, hint="force")

    def clear_cache_for(self, keys: list[str]) -> int:
        deleted = self._cache.bulk_delete(keys)
        for key in keys:
            self._event_log.add("cache_clear_manual", key, {})
        return deleted

